def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    """Improved version of `equation_v1` with quadratic term for gate voltage."""
    a0, a1, a2, b0, b1, b2 = parameters
    return a0 + a1 * gate_voltage_abs + a2 * (gate_voltage_abs ** 2) + b0 * drain_voltage_abs + b1 * (drain_voltage_abs ** 2)
